<style>
.inbox-list{display:grid;gap:14px}.inbox-row{display:block;text-decoration:none}.inbox-row.unread{border-left:4px solid #0aa0db}.inbox-meta{display:flex;align-items:center;flex-wrap:wrap;gap:10px;color:#66737a;font-size:14px}.inbox-row h2{font-size:20px;margin:9px 0}.inbox-body{white-space:pre-wrap;overflow-wrap:anywhere}.inbox-actions{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin-top:18px}.inbox-actions form{margin:0}.message-form{display:grid;gap:18px;max-width:820px}.message-form label{display:grid;gap:6px;font-weight:700}.message-form input,.message-form select,.message-form textarea{width:100%;margin:0}.message-thread{display:grid;gap:16px;margin:22px 0}.message-bubble{padding:20px;border:1px solid #dbe5e9;border-radius:12px;background:#fff}.message-bubble.from-dancepro{background:#edf8fd;border-color:#b4dfed}.message-bubble p:last-child{margin-bottom:0}.message-hint{color:#66737a;font-size:14px}.message-notice{margin-bottom:20px}.inbox-empty{padding:30px}.message-title{overflow-wrap:anywhere}
.message-advanced{border:1px solid var(--line);border-radius:8px}.message-advanced summary{padding:14px 16px;cursor:pointer;font-weight:750;color:#075d7e}.message-advanced summary:focus-visible{outline:2px solid var(--accent);outline-offset:3px}.message-advanced-fields{display:grid;gap:18px;padding:4px 16px 18px}
.notification-summary{display:flex;align-items:center;gap:16px;padding:20px;cursor:pointer;list-style:none}.notification-summary::-webkit-details-marker{display:none}.notification-summary:focus-visible{outline:2px solid var(--accent);outline-offset:-3px;border-radius:12px}.notification-summary time{display:flex;gap:12px;flex-shrink:0;font-size:14px;color:var(--muted)}.notification-heading{flex:1;min-width:0;font-weight:750;overflow-wrap:anywhere}.notification-status{font-size:12px;font-weight:750;padding:4px 9px;border-radius:20px;background:#edf2f4;color:#52636d;flex-shrink:0}.notification-status.is-unread{background:#e0f5ff;color:#087fab}.notification-toggle{display:grid;width:34px;height:34px;flex:0 0 34px;place-items:center;border-radius:50%;background:#eaf6fa;font-size:20px;color:#087fab;transition:transform .2s}.notification-row[open] .notification-toggle{transform:rotate(180deg)}.notification-details{padding:20px;border-top:1px solid var(--line)}@media(max-width:650px){.notification-summary{display:grid;grid-template-columns:1fr auto auto;gap:10px 12px}.notification-heading{grid-column:1/3;grid-row:2}.notification-toggle{grid-column:3;grid-row:1/3}.notification-summary time{flex-wrap:wrap;gap:4px 10px}}
.message-tabs .inbox-badge{margin-left:0;margin-right:7px}
.notification-read{flex-shrink:0;font-size:13px;padding:7px 10px;min-height:34px}.notification-read[hidden]{display:none}.notification-read:disabled{opacity:.6;cursor:wait}@media(max-width:650px){.notification-read{grid-column:1/3;grid-row:3;justify-self:start}.notification-toggle{grid-row:1/4}}
</style>
